style.css:
@-moz-document domain("youtube.com") {
body, #page-manager, ytd-app {
        background-color: #fcbcd4 !important; /* Light pink */
    }

    #masthead-container, #container, #header, #guide-content, #guide-renderer, ytd-mini-guide-renderer, #content {
        background-color: #fcbcd4 !important; /* Light pink for the top bar & sidebar */
    }

    ytd-masthead, ytd-guide-entry-renderer, ytd-guide-section-renderer, ytd-mini-guide-entry-renderer {
        background-color: #fcbcd4 !important;
        color: #000000 !important; /* Adjust text color if needed */
    }
}
